INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Binärbaum immer schneller als eine Hash-Tabelle bei Suchen?', 2, '[{"text": "Nein", "correct": true, "because": "O(log n) vs. O(1)"}, {"text": "Ja", "correct": false, "because": "Hash-Tabelle ist im Durchschnitt schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich für eine hierarchische Darstellung wie ein Organigramm?', 3, '[{"text": "Baum", "correct": true, "because": "Perfekt für Hierarchien"}, {"text": "Hash-Tabelle", "correct": false, "because": "Keine Hierarchie-Unterstützung"}, {"text": "Liste", "correct": false, "because": "Keine natürliche Baumstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen eine Hash-Tabelle effizient?', 5, '[{"text": "Gute Hash-Funktion", "correct": true, "because": "Minimiert Kollisionen"}, {"text": "Niedriger Lastfaktor", "correct": true, "because": "Hält O(1) stabil"}, {"text": "Sortierte Schlüssel", "correct": false, "because": "Nicht relevant"}, {"text": "Hohe Speichergröße", "correct": false, "because": "Nur sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein AVL-Baum bleibt immer ausbalanciert. b) Eine Hash-Tabelle ist immer ausbalanciert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hash-Tabelle hat kein Balancing"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Baums für schnelle Suchen?', 4, '[{"text": "Höhe", "correct": false, "because": "Bestimmt Laufzeit"}, {"text": "Balance", "correct": false, "because": "Wichtig für Effizienz"}, {"text": "Schlüsselanzahl", "correct": true, "because": "Weniger relevant als Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Hash-Tabelle mehr Speicher als ein Baum braucht?', 2, '[{"text": "Ja", "correct": true, "because": "Overhead durch Array"}, {"text": "Nein", "correct": false, "because": "Bäume haben oft weniger Overhead"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur ist besser für eine Aufgabe mit O(1) Zugriff?', 3, '[{"text": "Hash-Tabelle", "correct": true, "because": "Konstanter Zugriff"}, {"text": "B-Baum", "correct": false, "because": "O(log n)"}, {"text": "Binärbaum", "correct": false, "because": "O(log n) im Bestfall"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen eignen sich für eine Datenbank mit schnellen Abfragen?', 5, '[{"text": "Hash-Tabelle", "correct": true, "because": "O(1) für Schlüssel"}, {"text": "B-Baum", "correct": true, "because": "Optimiert für große Daten"}, {"text": "Array", "correct": false, "because": "O(n) Suche"}, {"text": "Stack", "correct": false, "because": "Keine Abfrage-Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Bäume sind gut für sortierte Daten. b) Hash-Tabellen sind auch dafür ideal. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hash-Tabellen sortieren nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Hash-Tabelle für große Datenmengen unwichtig?', 4, '[{"text": "Kollisionsmanagement", "correct": false, "because": "Kritisch für Effizienz"}, {"text": "Hash-Funktion", "correct": false, "because": "Bestimmt Verteilung"}, {"text": "Sortierfähigkeit", "correct": true, "because": "Nicht Zweck der Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat ein Baum immer eine bessere Laufzeit als eine Hash-Tabelle?', 2, '[{"text": "Nein", "correct": true, "because": "Hash-Tabelle ist O(1)"}, {"text": "Ja", "correct": false, "because": "Baum ist O(log n)"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen haben den Vorteil der Ordnung?', 4, '[{"text": "Baum", "correct": true, "because": "Natürlich sortiert"}, {"text": "Hash-Tabelle", "correct": false, "because": "Ungeordnet"}, {"text": "ArrayList", "correct": false, "because": "Nur durch Extra-Sortierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Hash-Tabellen bei Kollisionen nutzlos werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kollisionen werden verwaltet"}, {"text": "Ja", "correct": false, "because": "Effizienz sinkt nur leicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Baum für eine große Datenmenge?', 3, '[{"text": "Balance", "correct": true, "because": "Hält Laufzeit niedrig"}, {"text": "Speicherbedarf", "correct": false, "because": "Sekundär"}, {"text": "Einfügegeschwindigkeit", "correct": false, "because": "Weniger kritisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein B-Baum ist für Datenbanken optimiert. b) Eine Hash-Tabelle ist besser für sortierte Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hash-Tabelle sortiert nicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strukturen helfen bei schnellen Schlüssel-Wert-Abfragen?', 5, '[{"text": "Hash-Tabelle", "correct": true, "because": "O(1) Zugriff"}, {"text": "Baum", "correct": true, "because": "O(log n) für sortierte Daten"}, {"text": "Liste", "correct": false, "because": "O(n) Suche"}, {"text": "Queue", "correct": false, "because": "Keine Schlüssel-Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Hash-Tabelle für schnelle Zugriffe?', 3, '[{"text": "Hash-Funktion", "correct": false, "because": "Kern für Effizienz"}, {"text": "Lastfaktor", "correct": false, "because": "Beeinflusst Kollisionen"}, {"text": "Reihenfolge", "correct": true, "because": "Ungeordnet"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der Effizienz? Ist ein Baum immer ausbalanciert?', 3, '[{"text": "Nein", "correct": true, "because": "Nur bei speziellen Typen wie AVL"}, {"text": "Ja", "correct": false, "because": "Normale Bäume können schief sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Hash-Tabelle Duplikate erlaubt?', 2, '[{"text": "Nein", "correct": true, "because": "Schlüssel sind eindeutig"}, {"text": "Ja", "correct": false, "because": "Duplikate überschreiben Werte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich für eine Aufgabe mit sortierten Daten?', 4, '[{"text": "Baum", "correct": true, "because": "Natürlich sortiert, O(log n)"}, {"text": "Hash-Tabelle", "correct": false, "because": "Ungeordnet"}, {"text": "Array", "correct": false, "because": "Sortierung extra nötig"}]');
